// Functional guard
export const authGuard: CanActivateFn = (route, state) => {
  const auth = inject(AuthService);
  const router = inject(Router);
  return auth.isLoggedIn()
    ? true
    : router.createUrlTree(['/login'], { queryParams: { returnUrl: state.url } });
};

// canDeactivate guard: warn on unsaved form
export const unsavedChangesGuard: CanDeactivateFn<EditComponent> = (component) =>
  component.hasUnsavedChanges()
    ? confirm('You have unsaved changes. Leave anyway?')
    : true;

// Functional resolver: fetch user before navigation
export const userResolver: ResolveFn<User> = (route) => {
  const userService = inject(UserService);
  return userService.getById(route.paramMap.get('id')!);
};

// Route with resolver
const routes: Routes = [{
  path: 'users/:id',
  component: UserDetailComponent,
  resolve: { user: userResolver },
  canActivate: [authGuard],
  data: { animation: 'UserPage' }
}];

// Access resolved data in component
@Component({...})
export class UserDetailComponent {
  user = inject(ActivatedRoute).snapshot.data['user'] as User;
}

// PreloadAllModules
bootstrapApplication(AppComponent, {
  providers: [provideRouter(routes, withPreloading(PreloadAllModules))]
});

// Custom preloading strategy: only preload routes with data.preload = true
export const selectivePreload: PreloadingStrategy = {
  preload: (route, load) => route.data?.['preload'] ? load() : of(null)
};
